<?php
namespace IPS\mpcservers\Modules\Community;

use IPS\mpcservers\Modules\Core\Presentation;
use IPS\mpcservers\Modules\Core\OrdinaryTopic;
use IPS\mpcservers\Modules\Community\Crew;
use IPS\mpcservers\Modules\Community\CrewLock;
if (!\defined('\IPS\SUITE_UNIQUE_KEY')) { exit; }
class CrewForm
{
 public static function field($topic,$forum) {
  if (CrewLock::blocked($topic)) { $field=new \IPS\Helpers\Form\Custom('sps_crew_locked',NULL,FALSE,array('getHtml'=>function()use($topic){return '<section class="sps-crew-editor">'.CrewLock::notice($topic).'</section>';}));$field->label='Ekipa serwera';return $field; }
  $value=array();if($topic && $topic->tid)foreach(Crew::roster($topic->tid) as $r)$value[]=array('person_id'=>$r['person_id'],'member'=>$r['member_id']?\IPS\Member::load($r['member_id'])->name:'','external'=>$r['member_id']?'':$r['name'],'role'=>$r['role'],'since'=>$r['since_date']);
  $field=new \IPS\Helpers\Form\Custom('sps_crew',$value,FALSE,array('getHtml'=>function($el)use($forum){return static::html((array)$el->value,$forum);}),function($v)use($topic,$forum){if(!OrdinaryTopic::selected($topic))Crew::normalize($v,$topic,$forum);});
  $field->label='Ekipa serwera';return $field;
 }
 public static function html($value,$forum) {
  $e=array('IPS\\mpcservers\\Directory','esc');$roles=Crew::roles(Presentation::forumConfig($forum)['category']);
  $row=function($i,$v)use($e,$roles){
   $name='sps_crew['.$i.']';
   // Legacy identity defaults remain readable for old form fixtures and failed submissions.
   if(!array_key_exists('member',$v) && isset($v['identity'])){try{$old=Crew::resolve($v['identity']);$v['member']=$old['member_id']?\IPS\Member::load($old['member_id'])->name:'';$v['external']=$old['member_id']?'':$old['name'];$v['person_id']=$old['person_id'];}catch(\DomainException $e){$v['external']=$v['identity'];}}
   $personHtml='<div class="sps-member-search" data-member-search data-url="'.$e(Crew::url(array('do'=>'memberSearch'))).'"><input type="text" class="ipsInput ipsInput--text ipsInput--wide" data-member-query value="'.$e($v['member']??'').'" placeholder="Wpisz nick konta forum" autocomplete="off" aria-label="Wyszukaj konto forum" aria-autocomplete="list"><input type="hidden" data-member-value name="'.$name.'[member]" value="'.$e($v['member']??'').'"><div data-member-results></div><span data-member-status role="status" class="i-color_soft"></span></div>';
   $external=new \IPS\Helpers\Form\Text($name.'[external]',(string)($v['external']??''),FALSE,array('maxLength'=>120,'placeholder'=>'Nick osoby bez konta lub #ID z rejestru'));
   $role=new \IPS\Helpers\Form\Select($name.'[role]',(string)($v['role']??'owner'),FALSE,array('options'=>$roles,'parse'=>'normal'));
   $role->htmlId='sps_crew_role_'.$i;
   $dateValue=(string)($v['since']??'');
   $date=new \IPS\Helpers\Form\Date($name.'[since]',$dateValue!=='' && Presentation::validDate($dateValue)?new \IPS\DateTime($dateValue):NULL,FALSE,array('min'=>new \IPS\DateTime('1970-01-01'),'max'=>new \IPS\DateTime('today')));
   $display=trim((string)($v['member']??''))?:trim((string)($v['external']??''));
   $photo='<span class="sps-crew-avatar" aria-hidden="true"><i class="fa-solid fa-user"></i></span>';
   if(!empty($v['member'])){try{$member=\IPS\Member::load($v['member'],'name');if($member->member_id)$photo=\IPS\Theme::i()->getTemplate('global','core')->userPhoto($member,'small');}catch(\OutOfRangeException $ex){}}
   return '<div class="sps-crew-row"><header class="sps-crew-card-heading">'.$photo.'<div><strong data-crew-name>'.$e($display?:'Nowa osoba').'</strong><span data-crew-role>'.$e($roles[$v['role']??'owner']??'').'</span></div></header>' . '<input type="hidden" name="'.$name.'[person_id]" value="'.(int)($v['person_id']??0).'"><div class="sps-crew-person"><label class="ipsFieldRow__label">Konto forum (opcjonalnie)</label>'.$personHtml.'<span class="ipsFieldRow__desc">Wpisz co najmniej 3 znaki i wybierz konto z podpowiedzi.</span></div><div><label class="ipsFieldRow__label">Osoba bez konta'.$external->html().'</label><span class="ipsFieldRow__desc">Wypełnij tylko wtedy, gdy nie wybierasz konta forum.</span></div><div><label class="ipsFieldRow__label" for="'.$e($role->htmlId).'">Rola</label>'.$role->html().'</div><div><label class="ipsFieldRow__label">Od kiedy <span class="i-color_soft">(opcjonalnie)</span>'.$date->html().'</label></div><button type="button" class="ipsButton ipsButton--small ipsButton--inherit" data-remove><i class="fa-solid fa-trash" aria-hidden="true"></i> Usuń osobę</button></div>';

  };
  $out='<section class="sps-crew-editor"><div class="sps-crew-intro"><p>Wybierz konto forum albo pozostaw je puste i wpisz nick osoby spoza forum. Możesz dodawać kolejne osoby i przypisywać im role.</p><a class="ipsButton ipsButton--small ipsButton--inherit" href="'.$e(Crew::url()).'" target="_blank" rel="noopener"><i class="fa-solid fa-users" aria-hidden="true"></i> Rejestr osób</a></div><input type="hidden" name="sps_crew[__sent]" value="1"><div data-crew-rows>';
  $i=0;foreach($value as $k=>$v)if(is_array($v))$out.=$row($i++,$v);if(!$i)$out.=$row($i++,array());
  return $out.'</div><template>'.$row('__INDEX__',array()).'</template><button type="button" class="ipsButton ipsButton--small ipsButton--secondary" data-add><i class="fa-solid fa-plus" aria-hidden="true"></i> Dodaj osobę / rolę</button><p class="i-color_soft">Role opisują ekipę serwera i nie nadają uprawnień na forum. Historia pokazuje deklaracje autora i moderatorów.</p></section>'.static::assets();
 }
 public static function assets(){return <<<'HTML'
<style>
.sps-crew-editor{min-width:0}.sps-crew-editor[hidden]{display:none!important}.sps-crew-intro{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}.sps-crew-intro p{flex:1 1 300px;margin:0;line-height:1.7}.sps-crew-editor [data-crew-rows]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr));gap:16px;margin-bottom:20px}.sps-crew-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start;padding:20px;border:1px solid rgba(128,128,160,.25);border-radius:12px;background:rgba(128,128,160,.06);min-width:0}.sps-crew-row>div{min-width:0}.sps-crew-card-heading{grid-column:1/-1;display:flex;align-items:center;gap:12px;padding-bottom:16px;border-bottom:1px solid rgba(128,128,160,.2);min-width:0}.sps-crew-card-heading>div{min-width:0}.sps-crew-card-heading strong{display:block;font-size:17px;overflow-wrap:anywhere}.sps-crew-card-heading [data-crew-role]{display:block;font-size:12px;opacity:.75;margin-top:4px}.sps-crew-avatar,.sps-crew-card-heading>a{display:flex!important;align-items:center;justify-content:center;flex:0 0 48px;width:48px!important;height:48px!important;border-radius:50%;overflow:hidden;background:rgba(120,130,230,.14);font-size:24px;margin:0!important;float:none!important}.sps-crew-card-heading img{width:100%;height:100%;object-fit:cover}.sps-crew-row .ipsFieldRow_label{display:block;float:none;width:auto;text-align:left;margin:0 0 7px;padding:0;font-size:13px}.sps-crew-row .ipsFieldRow_desc{display:block;margin:6px 0 0;font-size:12px;line-height:1.5}.sps-crew-row input,.sps-crew-row select{max-width:100%;width:100%;min-width:0;box-sizing:border-box}.sps-crew-row .ipsSelectTree,.sps-crew-row .ipsField_autocomplete{max-width:100%;min-width:0;width:100%}.sps-crew-row [data-remove]{grid-column:1/-1;justify-self:end;margin:0}.sps-crew-page form>.ipsForm>.ipsFieldRow>.ipsFieldRow_label{display:none}.sps-crew-page .ipsFieldRow_content{margin-left:0}.sps-crew-page form>ul>.ipsFieldRow{padding-left:0;padding-right:0}.sps-crew-page .sps-crew-page-title{margin:0 0 8px;font-size:22px}.sps-crew-page .sps-crew-topic{display:inline-block;margin-bottom:20px}@media(max-width:550px){.sps-crew-row{grid-template-columns:minmax(0,1fr);padding:16px}.sps-crew-card-heading,.sps-crew-row [data-remove]{grid-column:1}.sps-crew-intro .ipsButton{width:100%}}
.sps-member-search{position:relative}.sps-member-search [data-member-results]{position:absolute;top:42px;left:0;right:0;z-index:30;background:var(--i-background_1);border-radius:6px;box-shadow:0 8px 24px #0005;max-height:260px;overflow:auto}.sps-member-search [data-member-results]:empty{display:none}.sps-member-search [data-member-results] button{display:block;width:100%;padding:10px 12px;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer}.sps-member-search [data-member-results] button:hover,.sps-member-search [data-member-results] button:focus{background:#828bff33}.sps-member-search [data-member-status]{display:block;font-size:12px;margin-top:5px}</style>
<script>(function(){if(window.spsCrewSearchReady)return;window.spsCrewSearchReady=true;
const state=new WeakMap();
document.addEventListener('input',function(event){const input=event.target.closest('[data-member-query]');if(!input)return;const box=input.closest('[data-member-search]'),hidden=box.querySelector('[data-member-value]'),list=box.querySelector('[data-member-results]'),status=box.querySelector('[data-member-status]');let old=state.get(box);if(old){clearTimeout(old.timer);if(old.controller)old.controller.abort();}const task={};state.set(box,task);hidden.value='';list.replaceChildren();const q=input.value.trim();input.setCustomValidity(q?'Wybierz konto z listy podpowiedzi.':'');status.textContent=q.length<3?'Wpisz co najmniej 3 znaki.':'';if(q.length<3)return;
task.timer=setTimeout(async()=>{const controller=new AbortController();task.controller=controller;const timeout=setTimeout(()=>controller.abort(),8000);status.textContent='Wyszukiwanie...';try{const url=new URL(box.dataset.url,location.href);url.searchParams.set('q',q);const response=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json'},signal:controller.signal});if(!response.ok)throw Error();const data=await response.json();if(state.get(box)!==task||!box.isConnected)return;if(!Array.isArray(data.results))throw Error();status.textContent=data.results.length?'Wybierz konto z listy.':'Nie znaleziono konta. Możesz wpisać nick w polu osoby bez konta.';for(const item of data.results){const button=document.createElement('button');button.type='button';button.textContent=item.name;button.addEventListener('click',()=>{input.value=item.name;hidden.value=item.name;input.setCustomValidity('');list.replaceChildren();status.textContent='Wybrano konto: '+item.name;const row=box.closest('.sps-crew-row');row.querySelector('[data-crew-name]').textContent=item.name;row.querySelector('[name$="[external]"]').value='';row.querySelector('[name$="[person_id]"]').value='0';});list.append(button);}}catch(e){if(state.get(box)===task)status.textContent='Nie udało się wyszukać kont. Zmień wpisany nick, aby spróbować ponownie.';}finally{clearTimeout(timeout);}},300);
});
document.addEventListener('keydown',event=>{const box=event.target.closest('[data-member-search]');if(!box)return;const buttons=Array.from(box.querySelectorAll('[data-member-results] button'));if(event.key==='Escape')box.querySelector('[data-member-results]').replaceChildren();if(event.key==='ArrowDown'&&buttons.length){event.preventDefault();buttons[(buttons.indexOf(event.target)+1)%buttons.length].focus();}if(event.key==='ArrowUp'&&buttons.length){event.preventDefault();buttons[(buttons.indexOf(event.target)+buttons.length-1)%buttons.length].focus();}});
})();
</script>
<script>(function(){function init(){document.querySelectorAll('.sps-crew-editor').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';let i=root.querySelectorAll('.sps-crew-row').length;root.addEventListener('change',e=>{const row=e.target.closest('.sps-crew-row');if(!row)return;if(e.target.name.endsWith('[role]'))row.querySelector('[data-crew-role]').textContent=e.target.selectedOptions[0].text;});root.addEventListener('input',e=>{const row=e.target.closest('.sps-crew-row');if(row&&e.target.name.endsWith('[external]'))row.querySelector('[data-crew-name]').textContent=e.target.value.trim()||'Nowa osoba';});root.addEventListener('click',e=>{if(e.target.closest('[data-remove]'))e.target.closest('.sps-crew-row').remove();if(e.target.closest('[data-add]')&&root.querySelectorAll('.sps-crew-row').length<40){const t=document.createElement('template');t.innerHTML=root.querySelector('template').innerHTML.replaceAll('__INDEX__',String(i++));const added=Array.from(t.content.children);root.querySelector('[data-crew-rows]').append(t.content);if(window.jQuery)jQuery(document).trigger('contentChange',[jQuery(added)]);}});});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();if(window.jQuery)jQuery(document).on('contentChange',init);})();</script>
HTML;
 }
}
